# ============================================================
# Alternative-splicing and functional-consequence statistics
# Figures S1 and S2
# ============================================================

library(IsoformSwitchAnalyzeR)
library(dplyr)
library(tidyr)

# ------------------------------------------------------------
# Load analyzed object generated by script 01
# ------------------------------------------------------------

aSwitchListAnalyzed <- readRDS(
  "results/aSwitchListAnalyzed.rds"
)

# ============================================================
# Figure S1
# Genome-wide alternative-splicing feature analysis
# ============================================================

s1_stats <- IsoformSwitchAnalyzeR::extractSplicingGenomeWide(
  aSwitchListAnalyzed,
  featureToExtract = "isoformUsage",
  splicingToAnalyze = "all",
  alpha = 0.05,
  dIFcutoff = 0.10,
  plot = FALSE,
  returnResult = TRUE
)

# ------------------------------------------------------------
# Recover Wilcoxon W statistics
# ------------------------------------------------------------

isoformsToAnalyze <- IsoformSwitchAnalyzeR:::extractSigData(
  switchAnalyzeRlist = aSwitchListAnalyzed,
  alpha = 0.05,
  dIFcutoff = 0.10,
  log2FCcutoff = 1,
  featureToExtract = "isoformUsage"
)

isoData <- aSwitchListAnalyzed$isoformFeatures %>%
  dplyr::mutate(
    comparison = paste(
      condition_1,
      condition_2,
      sep = " vs "
    )
  ) %>%
  dplyr::filter(
    iso_ref %in% isoformsToAnalyze
  ) %>%
  dplyr::select(
    iso_ref,
    isoform_id,
    comparison,
    IF1,
    IF2
  ) %>%
  dplyr::inner_join(
    aSwitchListAnalyzed$AlternativeSplicingAnalysis %>%
      dplyr::select(
        isoform_id,
        A3,
        A5,
        ATSS,
        ATTS,
        ES,
        IR,
        MEE,
        MES
      ),
    by = "isoform_id"
  )

s1_long <- isoData %>%
  tidyr::pivot_longer(
    cols = c(
      A3,
      A5,
      ATSS,
      ATTS,
      ES,
      IR,
      MEE,
      MES
    ),
    names_to = "category",
    values_to = "feature_present"
  ) %>%
  dplyr::filter(
    !is.na(feature_present)
  ) %>%
  dplyr::mutate(
    isoform_feature = paste(
      ifelse(
        feature_present == 0,
        "Without",
        "With"
      ),
      category
    )
  ) %>%
  tidyr::pivot_longer(
    cols = c(IF1, IF2),
    names_to = "condition_IF",
    values_to = "IF"
  )

s1_stats_with_W <- s1_long %>%
  dplyr::group_by(
    comparison,
    category,
    isoform_feature
  ) %>%
  dplyr::summarise(
    n = sum(condition_IF == "IF1"),
    W = unname(
      wilcox.test(
        IF[condition_IF == "IF1"],
        IF[condition_IF == "IF2"]
      )$statistic
    ),
    p_value = wilcox.test(
      IF[condition_IF == "IF1"],
      IF[condition_IF == "IF2"]
    )$p.value,
    .groups = "drop"
  ) %>%
  dplyr::mutate(
    FDR = p.adjust(
      p_value,
      method = "BH"
    )
  )

# ============================================================
# Figure S2
# Functional-consequence enrichment
# ============================================================

s2_stats <- IsoformSwitchAnalyzeR::extractConsequenceEnrichment(
  aSwitchListAnalyzed,
  consequencesToAnalyze = "all",
  alpha = 0.05,
  dIFcutoff = 0.10,
  countGenes = TRUE,
  plot = FALSE,
  returnResult = TRUE
)

# ============================================================
# Export results
# ============================================================

dir.create(
  "results",
  showWarnings = FALSE,
  recursive = TRUE
)

write.csv(
  s1_stats,
  "results/Figure_S1_IsoformSwitchAnalyzeR_statistics.csv",
  row.names = FALSE
)

write.csv(
  s1_stats_with_W,
  "results/Figure_S1_Wilcoxon_statistics.csv",
  row.names = FALSE
)

write.csv(
  s2_stats,
  "results/Figure_S2_consequence_statistics.csv",
  row.names = FALSE
)

# ============================================================
# Record R environment
# ============================================================

capture.output(
  sessionInfo(),
  file = "results/splicing_consequence_sessionInfo.txt"
)
